def is_point_on_segment(p, a, b):
    # Check if p is collinear with a and b
    # Using cross product to check collinearity: (a - p) × (b - p) should be 0
    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    # Check if p is between a and b (inclusive)
    def is_between(a, b, p):
        return (min(a[0], b[0]) <= p[0] <= max(a[0], b[0])) and (min(a[1], b[1]) <= p[1] <= max(a[1], b[1]))

    # If cross product is zero, points are collinear
    if cross(a, b, p) != 0:
        return False
    # Check if p is between a and b
    return is_between(a, b, p)
