def is_convex_polygon(points):
    def cross_product(o, a, b):
        # Compute the cross product of vectors OA and OB
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    n = len(points)
    if n < 3:
        return False

    # To check if all consecutive triplets have the same sign of cross product
    previous = None
    for i in range(n):
        o = points[i]
        a = points[(i + 1) % n]
        b = points[(i + 2) % n]
        cp = cross_product(o, a, b)
        if cp == 0:
            # All points are collinear, not a convex polygon
            return False
        if previous is None:
            previous = cp
        else:
            if (previous > 0 and cp < 0) or (previous < 0 and cp > 0):
                return False
        previous = cp

    return True
```

