def is_convex_polygon(points):
    n = len(points)
    if n < 3:
        return False

    def cross(o, a, b):
        # Compute the cross product of vectors OA and OB
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    # Check all consecutive triplets of points
    prev_cross = 0
    for i in range(n):
        a = points[i]
        b = points[(i + 1) % n]
        c = points[(i + 2) % n]
        cross_prod = cross(a, b, c)
        if cross_prod == 0:
            # Collinear points, not convex
            return False
        if i == 0:
            prev_cross = cross_prod
        else:
            if (cross_prod > 0 and prev_cross < 0) or (cross_prod < 0 and prev_cross > 0):
                # Change in sign of cross product means non-convex
                return False
            prev_cross = cross_prod

    return True
