def is_convex_polygon(points):
    def cross(p, q, r):
        # Compute the cross product of vectors (q - p) and (r - q)
        # If cross product is 0, points are collinear
        # Positive value means counter-clockwise turn, negative means clockwise
        return (q[0] - p[0]) * (r[1] - q[1]) - (q[1] - p[1]) * (r[0] - q[0])

    n = len(points)
    if n < 3:
        return False  # Not a polygon

    # Check all consecutive triplets of points
    # Use modulo to wrap around the end to the beginning
    previous = 0
    for i in range(n):
        current = cross(points[i], points[(i + 1) % n], points[(i + 2) % n])
        if current == 0:
            return False  # Collinear points, not convex
        if previous * current < 0:
            return False  # Change in direction, not convex
        previous = current

    return True
