def is_convex_polygon(points):
    n = len(points)
    if n < 3:
        return False  # Not a polygon

    # Compute the cross product of consecutive edges
    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    # Check the sign of all consecutive cross products
    sign = 0
    for i in range(n):
        a = points[i]
        b = points[(i + 1) % n]
        c = points[(i + 2) % n]
        cross_prod = cross(a, b, c)
        if cross_prod == 0:
            continue  # Collinear points, not considered convex
        if sign == 0:
            sign = 1 if cross_prod > 0 else -1
        elif (sign > 0 and cross_prod < 0) or (sign < 0 and cross_prod > 0):
            return False  # Change in direction, not convex

    return True
```

