def is_convex_polygon(points):
    def cross_product(o, a, b):
        # Vector OA = (a[0]-o[0], a[1]-o[1])
        # Vector OB = (b[0]-o[0], b[1]-o[1])
        # Cross product OA x OB = (a[0]-o[0])*(b[1]-o[1]) - (a[1]-o[1])*(b[0]-o[0])
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    n = len(points)
    if n < 3:
        return False  # A polygon must have at least 3 points

    # Check if all points are collinear
    # Using the first three points to check collinearity
    if cross_product(points[0], points[1], points[2]) == 0:
        return False

    # Check all consecutive triplets of points
    prev_cross = 0
    for i in range(n):
        o = points[i]
        a = points[(i + 1) % n]
        b = points[(i + 2) % n]
        cross = cross_product(o, a, b)
        if cross == 0:
            continue  # Collinear points, not a problem for convexity
        if (cross > 0 and prev_cross < 0) or (cross < 0 and prev_cross > 0):
            return False  # Change in direction (non-convex)
        prev_cross = cross

    return True
