def is_convex_polygon(points):
    def cross_product(p1, p2, p3):
        # Calculate the cross product of (p2 - p1) and (p3 - p1)
        return (p2[0] - p1[0]) * (p3[1] - p1[1]) - (p2[1] - p1[1]) * (p3[0] - p1[0])

    n = len(points)
    if n < 3:
        return False

    prev_sign = 0  # 0 means not yet set

    for i in range(n):
        p1 = points[i]
        p2 = points[(i + 1) % n]
        p3 = points[(i + 2) % n]

        cross = cross_product(p1, p2, p3)

        if cross == 0:
            # Collinear points, not a convex polygon
            return False

        if prev_sign == 0:
            prev_sign = 1 if cross > 0 else -1
        elif (cross > 0 and prev_sign < 0) or (cross < 0 and prev_sign > 0):
            # Change in sign means concave
            return False

    return True
```

