def equal_under_rotation(grid1, grid2):
    def rotate_90(grid):
        # Rotate a grid 90 degrees clockwise
        return [list(row)[::-1] for row in zip(*grid)]

    def rotate_180(grid):
        # Rotate a grid 180 degrees clockwise (equivalent to rotating 90 twice)
        return rotate_90(rotate_90(grid))

    def rotate_270(grid):
        # Rotate a grid 270 degrees clockwise (equivalent to rotating 90 three times)
        return rotate_90(rotate_180(grid))

    # Check if grid1 equals grid2 under any rotation
    return (grid1 == grid2 or
            rotate_90(grid1) == grid2 or
            rotate_180(grid1) == grid2 or
            rotate_270(grid1) == grid2)
