        return True  # Empty grid or single cell is valid

    rows, cols = len(grid), len(grid[0])
    expected_values = set()

    for i in range(rows):
        for j in range(cols):
            # Determine the expected value based on the sum of indices
            if (i + j) % 2 == 0:
                expected = 0
            else:
                expected = 1

            # Check if the current cell's value matches the expected pattern
            if grid[i][j] % 2 != expected:
                return False

    # Check that exactly two distinct values are used
    values = set(grid[i][j] for i in range(rows) for j in range(cols))
    return len(values) == 2
