def is_checkerboard(grid):
    if not grid or not grid[0]:
        return True  # Empty grid or single cell is valid

    rows, cols = len(grid), len(grid[0])
    expected = set()

    for i in range(rows):
        for j in range(cols):
            # Determine the expected value based on (i + j) parity
            if (i + j) % 2 == 0:
                expected_val = grid[0][0]
            else:
                expected_val = grid[0][1] if cols > 1 else grid[1][0] if rows > 1 else None

            if grid[i][j] != expected_val:
                return False

    # Ensure exactly two distinct values are used
    unique_vals = set()
    for row in grid:
        unique_vals.update(row)
        if len(unique_vals) > 2:
            return False

    return len(unique_vals) == 2
