def is_checkerboard(grid):
    if not grid or not grid[0]:
        return True  # Empty grid or single cell is valid

    rows = len(grid)
    cols = len(grid[0])

    # Determine the two expected values based on (row + col) parity
    val_even = grid[0][0]
    val_odd = grid[0][1] if cols > 1 else grid[1][0] if rows > 1 else None

    # If only one value exists, it's invalid unless it's a single cell
    if val_odd is None and rows * cols > 1:
        return False

    for i in range(rows):
        for j in range(cols):
            expected = val_even if (i + j) % 2 == 0 else val_odd
            if grid[i][j] != expected:
                return False

    return True
```

