def compare_semver(v1, v2):
    # Split the version strings into components
    v1_components = list(map(int, v1.split('.')))
    v2_components = list(map(int, v2.split('.')))

    # Compare each component numerically
    for c1, c2 in zip(v1_components, v2_components):
        if c1 < c2:
            return -1
        elif c1 > c2:
            return 1

    # If all compared components are equal, check lengths
    if len(v1_components) < len(v2_components):
        return -1
    elif len(v1_components) > len(v2_components):
        return 1
    else:
        return 0
```

