    # Find the operator position
    for i, char in enumerate(s):
        if char in "+-*/":
            op_index = i
            break

    # Split the string into left and right operands
    left = s[:op_index]
    right = s[op_index+1:]

    # Convert operands to integers
    a = int(left)
    b = int(right)

    # Perform the operation based on the operator
    if s[op_index] == '+':
        return a + b
    elif s[op_index] == '-':
        return a - b
    elif s[op_index] == '*':
        return a * b
    elif s[op_index] == '/':
        return a / b
```

