def parse_simple_expr(s):
    # Find the operator position
    for i, char in enumerate(s):
        if char in "+-*/":
            op_pos = i
            break

    # Split the string into left and right operands
    left = int(s[:op_pos])
    right = int(s[op_pos+1:])
    operator = s[op_pos]

    # Perform the operation
    if operator == '+':
        return left + right
    elif operator == '-':
        return left - right
    elif operator == '*':
        return left * right
    elif operator == '/':
        return left / right
