def parse_url_parts(url):
    # Split the URL into scheme and the rest
    if '://' not in url:
        return {'scheme': '', 'host': '', 'path': '', 'query': ''}

    scheme, rest = url.split('://', 1)

    # Split the rest into host, path, and query
    host_end = rest.find('/')
    query_pos = rest.find('?')

    if host_end == -1 and query_pos == -1:
        host = rest
        path = ''
        query = ''
    elif host_end == -1:
        host = rest[:query_pos]
        path = ''
        query = rest[query_pos+1:]
    elif query_pos == -1:
        host = rest[:host_end]
        path = rest[host_end:]
        query = ''
    else:
        if host_end < query_pos:
            host = rest[:host_end]
            path = rest[host_end:query_pos]
            query = rest[query_pos+1:]
        else:
            host = rest[:query_pos]
            path = rest[query_pos: host_end]
            query = rest[host_end+1:]

    return {'scheme': scheme, 'host': host, 'path': path, 'query': query}
```

