    # Remove the 'v' prefix if present
    if s.startswith('v'):
        s = s[1:]
    # Split the string by dots and convert each part to integer
    parts = list(map(int, s.split('.')))
    # Ensure exactly three parts (major, minor, patch)
    if len(parts) != 3:
        raise ValueError("Version string must contain exactly three parts")
    return tuple(parts)
