def parse_env_line(line):
    # Split the line into key and value parts on the first '='
    parts = line.split('=', 1)
    if len(parts) < 2:
        raise ValueError("Line does not contain an '=' character.")

    key, value_part = parts[0], parts[1]

    # Check if the value is quoted
    if len(value_part) >= 2 and value_part[0] == value_part[-1]:
        quote_char = value_part[0]
        # Check if the quote characters are matching and the value is at least two characters long
        if quote_char in ('"', "'") and len(value_part) > 1:
            value = value_part[1:-1]
        else:
            value = value_part
    else:
        value = value_part

    return (key, value)
```

