def parse_list_range_spec(spec):
    result = []
    tokens = spec.split(',')
    for token in tokens:
        if '-' in token:
            a, b = map(int, token.split('-'))
            result.extend(range(a, b + 1))
        else:
            result.append(int(token))
    return sorted(list(set(result)))
