def traffic_light_state(n_ticks, durations):
    red_ticks, green_ticks, yellow_ticks = durations
    cycle_length = red_ticks + green_ticks + yellow_ticks

    # Find the position in the cycle
    n_ticks %= cycle_length

    if n_ticks < red_ticks:
        return "RED"
    elif n_ticks < red_ticks + green_ticks:
        return "GREEN"
    elif n_ticks < red_ticks + green_ticks + yellow_ticks:
        return "YELLOW"
    else:
        return "RED"  # This case should not occur due to modulo operation
```

