def robot_grid_position(commands):
    x, y = 0, 0
    facing = 'N'

    # Direction mappings
    directions = {
        'N': (0, 1),
        'E': (1, 0),
        'S': (0, -1),
        'W': (-1, 0)
    }

    # Turn mappings
    turn_map = {
        'L': {
            'N': 'W',
            'W': 'S',
            'S': 'E',
            'E': 'N'
        },
        'R': {
            'N': 'E',
            'E': 'S',
            'S': 'W',
            'W': 'N'
        }
    }

    for cmd in commands:
        if cmd == 'F':
            dx, dy = directions[facing]
            x += dx
            y += dy
        elif cmd == 'L' or cmd == 'R':
            facing = turn_map[cmd][facing]

    return (x, y, facing)
```

