def robot_grid_position(commands):
    # Initial position and direction
    x, y = 0, 0
    facing = 'N'

    # Directions: North, East, South, West
    directions = ['N', 'E', 'S', 'W']

    for cmd in commands:
        if cmd == 'L':
            # Turn 90 degrees counter-clockwise
            index = directions.index(facing)
            facing = directions[(index - 1) % 4]
        elif cmd == 'R':
            # Turn 90 degrees clockwise
            index = directions.index(facing)
            facing = directions[(index + 1) % 4]
        elif cmd == 'F':
            # Move forward based on current direction
            if facing == 'N':
                y += 1
            elif facing == 'S':
                y -= 1
            elif facing == 'E':
                x += 1
            elif facing == 'W':
                x -= 1

    return (x, y, facing)
