    # Turn mapping: current direction -> new direction after L or R
    turn_map = {
        'N': {'L': 'W', 'R': 'E'},
        'E': {'L': 'N', 'R': 'S'},
        'S': {'L': 'E', 'R': 'W'},
        'W': {'L': 'S', 'R': 'N'}
    }

    for cmd in commands:
        if cmd == 'L' or cmd == 'R':
            facing = turn_map[facing][cmd]
        elif cmd == 'F':
            dx, dy = direction_map[facing]
            x += dx
            y += dy

    return (x, y, facing)
```

