def robot_vacuum_cleaned(commands, obstacles):
    # Convert obstacles to a set for O(1) lookups
    obstacle_set = set(obstacles)

    # Initialize robot's position and direction
    x, y = 0, 0
    direction = 'N'  # Start facing North

    # Define direction change for L and R
    direction_order = ['N', 'E', 'S', 'W']

    # Set of cleaned cells (including starting position)
    cleaned = {(0, 0)}

    for cmd in commands:
        if cmd == 'L':
            # Find index of current direction and move counter-clockwise
            idx = direction_order.index(direction)
            direction = direction_order[(idx - 1) % 4]
        elif cmd == 'R':
            # Find index of current direction and move clockwise
            idx = direction_order.index(direction)
            direction = direction_order[(idx + 1) % 4]
        elif cmd == 'F':
            # Calculate new position based on current direction
            if direction == 'N':
                new_x, new_y = x, y + 1
            elif direction == 'E':
                new_x, new_y = x + 1, y
            elif direction == 'S':
                new_x, new_y = x, y - 1
            elif direction == 'W':
                new_x, new_y = x - 1, y

            # Check if new position is not an obstacle
            if (new_x, new_y) not in obstacle_set:
                x, y = new_x, new_y

            # Add current position to cleaned cells
            cleaned.add((x, y))

    return len(cleaned)
```

