def undo_redo_state(commands):
    document = []
    redo_history = []

    for cmd in commands:
        if cmd[0] == "do":
            value = cmd[1]
            document.append(value)
            redo_history.clear()  # Clear redo history when a new "do" is performed
        elif cmd[0] == "undo":
            if document:
                # Move the last item from document to redo_history
                redo_history.append(document.pop())
        elif cmd[0] == "redo":
            if redo_history:
                # Move the last item from redo_history back to document
                document.append(redo_history.pop())

    return document
