def coffee_machine_credit(events, prices, stock):
    credit = 0
    total_dispensed = 0
    # Create a copy of the stock to avoid modifying the input
    final_stock = dict(stock)

    for op, value in events:
        if op == "insert":
            credit += value
        elif op == "select":
            drink = value
            if drink in prices and drink in final_stock:
                price = prices[drink]
                if final_stock[drink] > 0 and credit >= price:
                    credit -= price
                    final_stock[drink] -= 1
                    total_dispensed += 1

    return (credit, final_stock, total_dispensed)
```

