def queue_with_capacity_serve(events, capacity):
    queue = []
    for event in events:
        if event[0] == "arrive":
            person_id = event[1]
            queue.append(person_id)
        elif event[0] == "serve":
            # Remove up to `capacity` people from the front of the queue
            num_remove = min(len(queue), capacity)
            queue = queue[num_remove:]
    return queue
```

