def point_in_triangle(p, a, b, c):
    # Function to calculate the cross product of vectors (o, a) and (o, b)
    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    # Check if point p lies on the same side of the line ab as c
    def same_side(p1, p2, a, b):
        return cross(a, b, p1) * cross(a, b, p2) >= 0

    # Check if point p lies on the segment ab
    def on_segment(p, a, b):
        return (min(a[0], b[0]) <= p[0] <= max(a[0], b[0]) and
                min(a[1], b[1]) <= p[1] <= max(a[1], b[1]))

    # Check if p is on the edge ab
    if on_segment(p, a, b):
        return True
    # Check if p is on the edge bc
    if on_segment(p, b, c):
        return True
    # Check if p is on the edge ca
    if on_segment(p, c, a):
        return True

    # Check if p is on the same side of ab as c
    if not same_side(p, c, a, b):
        return False
    # Check if p is on the same side of bc as a
    if not same_side(p, a, b, c):
        return False
    # Check if p is on the same side of ca as b
    if not same_side(p, b, c, a):
        return False

    return True
```

