def classify_triangle_by_sides(p1, p2, p3):
    def distance(p, q):
        return ((p[0] - q[0]) ** 2 + (p[1] - q[1]) ** 2) ** 0.5

    a = distance(p1, p2)
    b = distance(p2, p3)
    c = distance(p3, p1)

    sides = [a, b, c]
    unique_sides = set(sides)

    if len(unique_sides) == 1:
        return 'equilateral'
    elif len(unique_sides) == 2:
        return 'isosceles'
    else:
        return 'scalene'
