def is_point_on_segment(p, a, b):
    # Check if point p is collinear with a and b
    # Using cross product to check collinearity
    # cross product of (p - a) and (b - a) should be zero
    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    # Check if p is collinear with a and b
    if cross(a, b, p) != 0:
        return False

    # Check if p lies between a and b
    def dot(v, w):
        return v[0] * w[0] + v[1] * w[1]

    def length_squared(v):
        return v[0] * v[0] + v[1] * v[1]

    # Ensure that the dot product of (p - a) and (b - a) is non-negative
    # and that the dot product of (p - b) and (a - b) is non-negative
    # This ensures that p is between a and b (inclusive)
    if dot((p[0] - a[0], p[1] - a[1]), (b[0] - a[0], b[1] - a[1])) < 0:
        return False
    if dot((p[0] - b[0], p[1] - b[1]), (a[0] - b[0], a[1] - b[1])) < 0:
        return False

    return True
