def is_convex_polygon(points):
    def cross_product(p1, p2, p3):
        # Calculate the cross product of (p2 - p1) and (p3 - p1)
        return (p2[0] - p1[0]) * (p3[1] - p1[1]) - (p2[1] - p1[1]) * (p3[0] - p1[0])

    n = len(points)
    if n < 3:
        return False  # Not a polygon

    # Check if all points are collinear
    cross = cross_product(points[0], points[1], points[2])
    if cross == 0:
        return False

    # Determine the sign of the first cross product
    sign = 1 if cross > 0 else -1

    for i in range(n):
        p1 = points[i]
        p2 = points[(i + 1) % n]
        p3 = points[(i + 2) % n]
        cross = cross_product(p1, p2, p3)
        if cross == 0:
            continue  # Collinear points, not considered convex
        if (cross * sign) < 0:
            return False  # Change in direction, not convex

    return True
```

