        # Calculate the cross product of vectors OA and OB
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    n = len(points)
    if n < 3:
        return False  # Not a polygon

    # To check convexity, all consecutive triplets must have the same sign of cross product
    prev_cross = 0
    for i in range(n):
        o, a, b = points[i], points[(i + 1) % n], points[(i + 2) % n]
        cross = cross_product(o, a, b)
        if cross == 0:
            return False  # Collinear points, not considered convex
        if i == 0:
            prev_cross = cross
        elif (cross * prev_cross) < 0:
            return False  # Change in direction, not convex
        prev_cross = cross
    return True
