def equal_under_rotation(grid1, grid2):
    def rotate90(grid):
        # Rotate 90 degrees clockwise
        n = len(grid)
        m = len(grid[0])
        return [[grid[n - j - 1][i] for j in range(n)] for i in range(m)]

    def rotate180(grid):
        # Rotate 180 degrees clockwise (equivalent to two 90-degree rotations)
        return rotate90(rotate90(grid))

    def rotate270(grid):
        # Rotate 270 degrees clockwise (equivalent to three 90-degree rotations)
        return rotate90(rotate90(rotate90(grid)))

    # Check if any rotation of grid1 matches grid2
    return (grid1 == grid2 or
            rotate90(grid1) == grid2 or
            rotate180(grid1) == grid2 or
            rotate270(grid1) == grid2)
