def count_paths(grid):
    m = len(grid)
    n = len(grid[0])

    # If start or end cell is blocked, return 0
    if grid[0][0] == 1 or grid[m-1][n-1] == 1:
        return 0

    # Initialize a 2D DP array
    dp = [[0 for _ in range(n)] for _ in range(m)]
    dp[0][0] = 1  # Starting point has one way to reach itself

    # Fill the first row
    for j in range(1, n):
        if grid[0][j] == 0:
            dp[0][j] = dp[0][j-1]
        else:
            break  # Obstacle encountered, no further paths in this row

    # Fill the first column
    for i in range(1, m):
        if grid[i][0] == 0:
            dp[i][0] = dp[i-1][0]
        else:
            break  # Obstacle encountered, no further paths in this column

    # Fill the rest of the DP table
    for i in range(1, m):
        for j in range(1, n):
            if grid[i][j] == 0:
                dp[i][j] = dp[i-1][j] + dp[i][j-1]
            else:
                dp[i][j] = 0  # Blocked cell, no path through here

    return dp[m-1][n-1]
