def is_checkerboard(grid):
    if not grid or not grid[0]:
        return True

    rows = len(grid)
    cols = len(grid[0])

    # Determine the expected values based on (i + j) % 2
    for i in range(rows):
        for j in range(cols):
            current = grid[i][j]
            expected = (i + j) % 2
            # Check if the current value matches the expected pattern
            if (expected == 0 and current != grid[0][0]) or (expected == 1 and current != grid[0][1]):
                return False
            # Check neighbors
            if i > 0 and grid[i][j] == grid[i - 1][j]:
                return False
            if j > 0 and grid[i][j] == grid[i][j - 1]:
                return False

    return True
```

