    if '://' in url:
        scheme, rest = url.split('://', 1)
    else:
        scheme = ''
        rest = url

    # Split the rest into host and the remaining parts
    if '/' in rest and '?' not in rest:
        host, path = rest.split('/', 1)
        query = ''
    elif '?' in rest and '/' not in rest:
        host = rest.split('?', 1)[0]
        path = ''
        query = rest.split('?', 1)[1]
    elif '/' in rest and '?' in rest:
        # Split on '?' first to get query
        if rest.index('/') < rest.index('?'):
            host_part, rest_after_host = rest.split('/', 1)
            path_query = rest_after_host.split('?', 1)
            path = '/' + path_query[0]
            query = path_query[1]
        else:
            host_part, rest_after_host = rest.split('?', 1)
            path = ''
            query = rest_after_host
            # Now find the host from host_part
            if '/' in host_part:
                host = host_part.split('/', 1)[0]
            else:
                host = host_part
    else:
        host = rest
        path = ''
        query = ''

    return {
        'scheme': scheme,
        'host': host,
        'path': path,
        'query': query
    }
```

