def parse_url_parts(url):
    # Split the URL into scheme and the rest
    if '://' not in url:
        raise ValueError("Invalid URL format: missing scheme separator '://'")
    scheme, rest = url.split('://', 1)

    # Split the rest into host and the remaining parts
    host_end = rest.find('/')  # Find the first '/' which could be start of path or end of host
    if host_end == -1:
        host_end = rest.find('?')  # If no '/', check for '?'
    if host_end == -1:
        host = rest
        path = ''
        query = ''
    else:
        host = rest[:host_end]
        remaining = rest[host_end:]

        # Split path and query
        if '?' in remaining:
            path, query = remaining.split('?', 1)
        else:
            path = remaining
            query = ''

    return {
        'scheme': scheme,
        'host': host,
        'path': path,
        'query': query
    }
```

