    cycle_length = red + green + yellow
    if cycle_length == 0:
        return "RED"  # Avoid division by zero, though durations should be positive
    remainder = n_ticks % cycle_length
    if remainder < red:
        return "RED"
    elif remainder < red + green:
        return "GREEN"
    else:
        return "YELLOW"
