    facing = 'N'

    # Direction mappings
    direction_map = {
        'N': (0, 1),
        'E': (1, 0),
        'S': (0, -1),
        'W': (-1, 0)
    }

    # Turning mappings
    turn_map = {
        'L': {'N': 'W', 'W': 'S', 'S': 'E', 'E': 'N'},
        'R': {'N': 'E', 'E': 'S', 'S': 'W', 'W': 'N'}
    }

    for cmd in commands:
        if cmd == 'L' or cmd == 'R':
            facing = turn_map[cmd][facing]
        elif cmd == 'F':
            dx, dy = direction_map[facing]
            x += dx
            y += dy

    return (x, y, facing)
