def thermostat_mode(events, initial_target):
    target = initial_target
    mode = "IDLE"

    for event in events:
        op, value = event
        if op == "set_target":
            target = value
        elif op == "read":
            current_temp = value
            if current_temp < target:
                mode = "HEAT"
            elif current_temp > target:
                mode = "COOL"
            else:
                mode = "IDLE"

    return mode
```

