def bounded_counter(events, cap):
    counter = 0
    for event in events:
        if event == "inc":
            if counter < cap:
                counter += 1
        elif event == "dec":
            if counter > 0:
                counter -= 1
        elif event == "reset":
            counter = 0
    return counter
```

