def robot_vacuum_cleaned(commands, obstacles):
    # Convert obstacles to a set for O(1) lookups
    obstacle_set = set(obstacles)

    # Initialize position and direction
    x, y = 0, 0
    direction = 'N'

    # Set of cleaned cells (including starting position)
    cleaned = set()
    cleaned.add((x, y))

    # Direction mappings
    direction_map = {
        'N': (0, 1),
        'E': (1, 0),
        'S': (0, -1),
        'W': (-1, 0)
    }

    # Turn mappings
    turn_map = {
        'L': {'N': 'W', 'W': 'S', 'S': 'E', 'E': 'N'},
        'R': {'N': 'E', 'E': 'S', 'S': 'W', 'W': 'N'}
    }

    for cmd in commands:
        if cmd == 'L' or cmd == 'R':
            direction = turn_map[cmd][direction]
        elif cmd == 'F':
            dx, dy = direction_map[direction]
            new_x = x + dx
            new_y = y + dy
            if (new_x, new_y) not in obstacle_set:
                x, y = new_x, new_y
            cleaned.add((x, y))

    return len(cleaned)
```

