def elevator_sweep_stops(start_floor, direction, requests, top_floor):
    stops = []
    current_floor = start_floor
    requested_floors = set(requests)

    # Check if start_floor is requested
    if current_floor in requested_floors:
        stops.append(current_floor)
        requested_floors.remove(current_floor)

    while True:
        next_floor = current_floor + direction
        if (direction == 1 and next_floor > top_floor) or (direction == -1 and next_floor < 1):
            break
        current_floor = next_floor
        if current_floor in requested_floors:
            stops.append(current_floor)
            requested_floors.remove(current_floor)

    # Check the final floor (top_floor or 1) if not already checked
    if direction == 1 and current_floor != top_floor:
        current_floor = top_floor
        if current_floor in requested_floors:
            stops.append(current_floor)
    elif direction == -1 and current_floor != 1:
        current_floor = 1
        if current_floor in requested_floors:
            stops.append(current_floor)

    return stops
```

