def register_finalized_totals(events):
    totals = []
    current_transaction = []

    for event in events:
        if event[0] == "scan":
            price = event[1]
            current_transaction.append(price)
        elif event[0] == "void":
            if current_transaction:
                current_transaction.pop()
        elif event[0] == "pay":
            totals.append(sum(current_transaction))
            current_transaction = []

    return totals
```

