def light_switch_group(n, events):
    lights = [False] * n
    for event in events:
        if event[0] == "toggle":
            idx = event[1]
            lights[idx] = not lights[idx]
        elif event[0] == "toggle_all":
            lights = [not light for light in lights]
        elif event[0] == "reset":
            lights = [False] * n
    return lights
```

