def is_convex_polygon(points):
    def cross(o, a, b):
        # Compute the cross product of vectors OA and OB
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    n = len(points)
    if n < 3:
        return False

    # Ensure the points are in order and check all consecutive triplets
    prev_cross = 0
    for i in range(n):
        a = points[i]
        b = points[(i + 1) % n]
        c = points[(i + 2) % n]
        cross_product = cross(a, b, c)

        if cross_product == 0:
            # Collinear points, not a convex polygon
            return False

        if i == 0:
            prev_cross = cross_product
        else:
            if (cross_product > 0 and prev_cross < 0) or (cross_product < 0 and prev_cross > 0):
                # Change in direction, not convex
                return False
            prev_cross = cross_product

    return True
```

