def count_points_in_circle(points, center, radius):
    cx, cy = center
    count = 0
    for (x, y) in points:
        distance_squared = (x - cx) ** 2 + (y - cy) ** 2
        if distance_squared <= radius ** 2:
            count += 1
    return count
