def rotate_90_clockwise(grid):
    if not grid or not grid[0]:
        return []
    rows, cols = len(grid), len(grid[0])
    result = [[0] * rows for _ in range(cols)]
    for i in range(rows):
        for j in range(cols):
            result[j][rows - 1 - i] = grid[i][j]
    return result
```

