def anti_diagonal(grid):
    if not grid or not grid[0]:
        return []
    rows = len(grid)
    cols = len(grid[0])
    result = []
    for i in range(rows + cols - 1):
        if i < cols:
            row = 0
            col = i
        else:
            row = i - cols + 1
            col = cols - 1
        if row < rows and col >= 0:
            result.append(grid[row][col])
    return result
```

