        return 0

    # Initialize a 2D array to store the number of paths to each cell
    dp = [[0] * n for _ in range(m)]
    dp[0][0] = 1  # Starting point has one path

    # Fill the first row
    for j in range(1, n):
        if grid[0][j] == 0:
            dp[0][j] = dp[0][j-1]
        else:
            break  # Obstacle encountered, no further paths in this row

    # Fill the first column
    for i in range(1, m):
        if grid[i][0] == 0:
            dp[i][0] = dp[i-1][0]
        else:
            break  # Obstacle encountered, no further paths in this column

    # Fill the rest of the dp table
    for i in range(1, m):
        for j in range(1, n):
            if grid[i][j] == 0:
                dp[i][j] = dp[i-1][j] + dp[i][j-1]
            else:
                dp[i][j] = 0  # Blocked cell, no paths through here

    return dp[m-1][n-1]
```

