def parse_ini_line(line):
    # Split the line on the '=' sign, allowing for optional whitespace around it
    parts = line.split('=')
    if len(parts) < 2:
        # If there's no '=', return the whole line as key and empty string as value
        return (line.strip(), '')
    key_part, value_part = parts[0], '='.join(parts[1:])
    # Strip whitespace from key and value
    key = key_part.strip()
    value = value_part.strip()
    return (key, value)
```

