def parse_url_parts(url):
    # Split the URL into scheme and the rest
    scheme_end = url.find('://')
    if scheme_end == -1:
        # No scheme found, default scheme is empty
        scheme = ''
        rest = url
    else:
        scheme = url[:scheme_end]
        rest = url[scheme_end+3:]

    # Split the rest into host and the rest
    host_end = rest.find('/')
    if host_end == -1:
        host_end = rest.find('?')
    if host_end == -1:
        host = rest
        path = ''
        query = ''
    else:
        host = rest[:host_end]
        remaining = rest[host_end:]
        if remaining.startswith('/'):
            path_start = host_end
        else:
            path_start = -1

        if '?' in remaining:
            query_start = remaining.find('?')
            path = remaining[:query_start]
            query = remaining[query_start+1:]
        else:
            path = remaining
            query = ''

    return {
        'scheme': scheme,
        'host': host,
        'path': path,
        'query': query
    }
```

```python
def parse_url_parts(url):
    # Split the URL into scheme and the rest
    if '://' not in url:
        return {'scheme': '', 'host': '', 'path': '', 'query': ''}

    scheme, rest = url.split('://', 1)

    # Split the rest into host, path, and query
    host_part = rest.split('/', 1)
    host = host_part[0]

    if len(host_part) == 1:
        path = ''
        query = ''
    else:
        path_part = host_part[1]
        if '?' in path_part:
            path, query = path_part.split('?', 1)
        else:
            path = path_part
            query = ''

    return {'scheme': scheme, 'host': host, 'path': '/' + path if path else '', 'query': query}
```

