def parse_env_line(line):
    # Split the line on the first '=' to separate key and value
    parts = line.split('=', 1)
    if len(parts) < 2:
        return (line, '')  # Handle cases where there's no '='

    key = parts[0]
    value_part = parts[1]

    # Check if the value is quoted
    if len(value_part) >= 2 and value_part[0] == value_part[-1]:
        quote_char = value_part[0]
        if quote_char in ('"', "'"):
            # Remove the surrounding quotes
            value = value_part[1:-1]
        else:
            # Not a valid quote, use the value as-is
            value = value_part
    else:
        # Value is not quoted
        value = value_part

    return (key, value)
```

