    # Split the line into key and value parts based on the first '='
    parts = line.split('=', 1)
    if len(parts) != 2:
        raise ValueError("Invalid line format: missing '='")
    key, value_part = parts

    # Check if the value is quoted
    if len(value_part) >= 2 and value_part[0] == value_part[-1]:
        quote_char = value_part[0]
        # Ensure it's a valid quoted string (at least two characters)
        if quote_char in ('"', "'") and len(value_part) >= 2:
            # Strip the quotes
            value = value_part[1:-1]
        else:
            value = value_part
    else:
        value = value_part

    return (key, value)
```

