def traffic_light_state(n_ticks, durations):
    red_ticks, green_ticks, yellow_ticks = durations
    cycle_length = red_ticks + green_ticks + yellow_ticks
    if cycle_length == 0:
        return "RED"  # Avoid division by zero, though durations should be positive

    # Find the position in the cycle
    position_in_cycle = n_ticks % cycle_length

    if position_in_cycle < red_ticks:
        return "RED"
    elif position_in_cycle < red_ticks + green_ticks:
        return "GREEN"
    elif position_in_cycle < red_ticks + green_ticks + yellow_ticks:
        return "YELLOW"
    else:
        return "RED"  # This case should not occur due to modulo
```

