def vending_machine_credit(events):
    credit = 0
    items_dispensed = 0
    for op, value in events:
        if op == "insert":
            credit += value
        elif op == "select":
            if credit >= value:
                credit -= value
                items_dispensed += 1
    return (credit, items_dispensed)
```

