            if event == "start":
                state = "RUNNING"
        elif state == "RUNNING":
            if event == "pause":
                state = "PAUSED"
            elif event == "stop":
                state = "OFF"
        elif state == "PAUSED":
            if event == "resume":
                state = "RUNNING"
            elif event == "stop":
                state = "OFF"
    return state
```

