def two_player_score(events):
    p1_score = 0
    p2_score = 0
    for player, pts in events:
        if player == "P1":
            p1_score += pts
            if p1_score < 0:
                p1_score = 0
        elif player == "P2":
            p2_score += pts
            if p2_score < 0:
                p2_score = 0
    return (p1_score, p2_score)
```

