```python
def traffic_light_log(n_ticks, durations):
    red_ticks, green_ticks, yellow_ticks = durations
    cycle_length = red_ticks + green_ticks + yellow_ticks
    result = []

    for tick in range(n_ticks):
        mod_tick = tick % cycle_length
        if mod_tick < red_ticks:
            result.append("RED")
        elif mod_tick < red_ticks + green_ticks:
            result.append("GREEN")
        elif mod_tick < red_ticks + green_ticks + yellow_ticks:
            result.append("YELLOW")

    return result
```

