def intersection_car_pass_count(events, green_duration):
    passed = 0
    for tick, direction in events:
        # Determine if the light is green for the given direction at the given tick
        # N/S phase: even tick (0, 2, 4, ...) if green_duration is 5, then 0-4, 5-9, etc.
        # E/W phase: odd tick (1, 3, 5, ...) if green_duration is 5, then 1-5, 6-10, etc.
        phase = tick // green_duration
        if phase % 2 == 0:
            # N/S green
            if direction in ['N', 'S']:
                passed += 1
        else:
            # E/W green
            if direction in ['E', 'W']:
                passed += 1
    return passed
```

