    for event in events:
        if event[0] == "add":
            item = event[1]
            qty = event[2]
            price = event[3]
            if item in cart:
                cart[item] += qty
                # Update the price to the latest one if needed
                cart[item + "_price"] = price
            else:
                cart[item] = qty
                cart[item + "_price"] = price
        elif event[0] == "remove":
            item = event[1]
            qty = event[2]
            if item in cart and cart[item] > 0:
                cart[item] -= qty
                if cart[item] <= 0:
                    del cart[item]
                    del cart[item + "_price"]
        elif event[0] == "clear":
            cart.clear()

    total = 0
    for item in cart:
        if item.endswith("_price"):
            continue
        price_key = item + "_price"
        if price_key in cart:
            total += cart[item] * cart[price_key]

    return total
