            if item in cart:
                cart[item] -= qty
                if cart[item] <= 0:
                    del cart[item]
                    # Also remove the price entry if it exists
                    if item + "_price" in cart:
                        del cart[item + "_price"]
        elif event[0] == "clear":
            cart.clear()

    total = 0
    for item in cart:
        if "_price" in item:
            continue
        price_key = item + "_price"
        if price_key in cart:
            total += cart[item] * cart[price_key]
    return total
