def robot_vacuum_cleaned(commands, obstacles):
    # Convert obstacles to a set for O(1) lookups
    obstacle_set = set(obstacles)

    # Initialize position and direction
    x, y = 0, 0
    direction = 'N'  # Starting direction is North

    # Set of cleaned cells, starting with (0, 0)
    cleaned = {(0, 0)}

    # Map directions to delta x and delta y
    direction_deltas = {
        'N': (0, 1),
        'E': (1, 0),
        'S': (0, -1),
        'W': (-1, 0)
    }

    # Process each command
    for cmd in commands:
        if cmd == 'L':
            # Turn left (counter-clockwise)
            if direction == 'N':
                direction = 'W'
            elif direction == 'W':
                direction = 'S'
            elif direction == 'S':
                direction = 'E'
            elif direction == 'E':
                direction = 'N'
        elif cmd == 'R':
            # Turn right (clockwise)
            if direction == 'N':
                direction = 'E'
            elif direction == 'E':
                direction = 'S'
            elif direction == 'S':
                direction = 'W'
            elif direction == 'W':
                direction = 'N'
        elif cmd == 'F':
            # Move forward
            dx, dy = direction_deltas[direction]
            new_x = x + dx
            new_y = y + dy

            # Check if the new position is not an obstacle
            if (new_x, new_y) not in obstacle_set:
                x, y = new_x, new_y

        # Add current position to cleaned cells
        cleaned.add((x, y))

    return len(cleaned)
