def undo_redo_state(commands):
    document = []
    redo_history = []

    for command in commands:
        if command[0] == "do":
            value = command[1]
            document.append(value)
            redo_history.clear()
        elif command[0] == "undo":
            if document:
                value = document.pop()
                redo_history.append(value)
        elif command[0] == "redo":
            if redo_history:
                value = redo_history.pop()
                document.append(value)

    return document
