def rectangles_overlap(r1, r2):
    # Check if the rectangles do not overlap (no overlap in x or y direction)
    # They do not overlap if one is completely to the left, right, above, or below the other
    if r1[2] <= r2[0] or r2[2] <= r1[0]:
        return False
    if r1[3] <= r2[1] or r2[3] <= r1[1]:
        return False
    return True
