def is_point_on_segment(p, a, b):
    # Check if point p lies on the line segment between a and b
    # First, check if p is collinear with a and b
    # The cross product (b - a) x (p - a) should be zero
    # Then, check if p lies between a and b using dot product
    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    def dot(o, a, b):
        return (a[0] - o[0]) * (b[0] - o[0]) + (a[1] - o[1]) * (b[1] - o[1])

    # Check collinearity
    if cross(a, b, p) != 0:
        return False

    # Check if p lies between a and b
    if dot(a, b, p) < 0 or dot(b, a, p) < 0:
        return False

    return True
```

