def is_point_on_segment(p, a, b):
    # Check if p lies on the line defined by a and b
    # Check if p is between a and b (inclusive)
    # First, check if the cross product is zero (collinear)
    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    # Check if p is collinear with a and b
    if cross(a, b, p) != 0:
        return False

    # Check if p lies between a and b (inclusive)
    def dot(v, w):
        return v[0] * w[0] + v[1] * w[1]

    def length(v):
        return (v[0]**2 + v[1]**2)**0.5

    # Check if p is between a and b by comparing dot products
    # If the dot product of (p - a) and (b - a) is between 0 and the square of the length of (b - a)
    # Then p lies on the segment
    ap = (p[0] - a[0], p[1] - a[1])
    ab = (b[0] - a[0], b[1] - a[1])

    if dot(ap, ab) < 0:
        return False

    if length(ap) > length(ab):
        return False

    return True
```

