def is_convex_polygon(points):
    def cross(o, a, b):
        # Vector OA cross vector OB
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    n = len(points)
    if n < 3:
        return False

    # Determine the direction (clockwise or counter-clockwise)
    direction = None
    for i in range(n):
        a = points[i]
        b = points[(i + 1) % n]
        c = points[(i + 2) % n]
        cross_product = cross(a, b, c)
        if cross_product == 0:
            # Collinear points, not a convex polygon
            return False
        if direction is None:
            direction = 1 if cross_product > 0 else -1
        elif (cross_product > 0 and direction == -1) or (cross_product < 0 and direction == 1):
            return False
    return True
```

