def is_square(p1, p2, p3, p4):
    def dist_sq(p, q):
        return (p[0] - q[0]) ** 2 + (p[1] - q[1]) ** 2

    points = [p1, p2, p3, p4]
    distances = []

    # Calculate squared distances between all consecutive points
    for i in range(4):
        distances.append(dist_sq(points[i], points[(i + 1) % 4]))

    # Check if there are exactly two distinct distances (side and diagonal)
    # and that the smaller one appears 4 times (sides), and the larger appears 2 times (diagonals)
    distances.sort()
    if distances[0] == distances[1] == distances[2] == distances[3] and distances[3] == distances[4]:
        return True
    elif distances[0] == distances[1] == distances[2] and distances[3] == distances[4] and distances[2] * 2 == distances[3]:
        return True
    elif distances[0] == distances[1] and distances[2] == distances[3] and distances[0] * 2 == distances[2]:
        return True
    else:
        return False
```

