    def rotate_180(grid):
        return rotate_clockwise(rotate_clockwise(grid))

    def rotate_270(grid):
        return rotate_clockwise(rotate_180(grid))

    if grid1 == grid2:
        return True
    if rotate_clockwise(grid1) == grid2:
        return True
    if rotate_180(grid1) == grid2:
        return True
    if rotate_270(grid1) == grid2:
        return True
    return False
