def is_checkerboard(grid):
    if not grid or not grid[0]:
        return True

    rows = len(grid)
    cols = len(grid[0])

    for i in range(rows):
        for j in range(cols):
            current = grid[i][j]
            # Check top neighbor
            if i > 0 and grid[i-1][j] == current:
                return False
            # Check left neighbor
            if j > 0 and grid[i][j-1] == current:
                return False
            # Check if the value is consistent with the checkerboard pattern
            expected = 1 if (i + j) % 2 == 0 else 2
            if current != expected:
                return False

    return True
```

