```python
def parse_version_tuple(s):
    # Remove the 'v' prefix if present
    if s.startswith('v'):
        s = s[1:]
    # Split the string by dots and convert each part to integer
    parts = list(map(int, s.split('.')))
    # Ensure there are exactly three parts
    if len(parts) != 3:
        raise ValueError("Version string must have exactly three components")
    return tuple(parts)
```

