```python
def parse_list_range_spec(spec):
    result = []
    parts = spec.split(',')
    for part in parts:
        if '-' in part:
            a, b = map(int, part.split('-'))
            result.extend(range(a, b + 1))
        else:
            result.append(int(part))
    return sorted(list(set(result)))
```

