def traffic_light_state(n_ticks, durations):
    red, green, yellow = durations
    cycle_length = red + green + yellow
    if cycle_length == 0:
        return "RED"  # Avoid division by zero, though durations are likely positive
    mod = n_ticks % cycle_length
    if mod < red:
        return "RED"
    elif mod < red + green:
        return "GREEN"
    else:
        return "YELLOW"
```

