def shopping_cart_total(events):
    cart = {}

    for event in events:
        if event[0] == "add":
            item = event[1]
            qty = event[2]
            price = event[3]
            if item in cart:
                cart[item] += qty
                # Update the price to the latest one if necessary (assuming we only need the latest price)
                # Here, we assume the latest price is the one provided in the event
                # If we need to track price per item, we would need a separate dictionary
                # For this problem, we just use the latest price provided in the event
            else:
                cart[item] = qty
            # Store the price in the cart as well (we can use a dictionary of dictionaries)
            # For simplicity, let's assume that the price is the same for all quantities of the item
            # and we just store the most recent price
            cart[item + "_price"] = price

        elif event[0] == "remove":
            item = event[1]
            qty = event[2]
            if item in cart:
                if cart[item] > qty:
                    cart[item] -= qty
                else:
                    del cart[item]
                    # Also remove the price entry if the item is removed
                    if item + "_price" in cart:
                        del cart[item + "_price"]

        elif event[0] == "clear":
            cart.clear()

    # Calculate the total cost
    total = 0
    for item in cart:
        if "_price" in item:
            continue
        price_key = item + "_price"
        if price_key in cart:
            total += cart[item] * cart[price_key]

    return total
