def robot_vacuum_cleaned(commands, obstacles):
    # Set of obstacles for quick lookup
    obstacle_set = set(obstacles)
    # Set of cleaned cells
    cleaned = set()
    # Initial position and direction
    x, y = 0, 0
    direction = "N"
    # Add starting position to cleaned
    cleaned.add((x, y))

    # Direction mapping
    directions = {
        "N": (0, 1),
        "E": (1, 0),
        "S": (0, -1),
        "W": (-1, 0)
    }

    # Process each command
    for cmd in commands:
        if cmd == "L":
            # Turn counter-clockwise
            if direction == "N":
                direction = "W"
            elif direction == "W":
                direction = "S"
            elif direction == "S":
                direction = "E"
            elif direction == "E":
                direction = "N"
        elif cmd == "R":
            # Turn clockwise
            if direction == "N":
                direction = "E"
            elif direction == "E":
                direction = "S"
            elif direction == "S":
                direction = "W"
            elif direction == "W":
                direction = "N"
        elif cmd == "F":
            dx, dy = directions[direction]
            new_x = x + dx
            new_y = y + dy
            # Check if new position is not an obstacle
            if (new_x, new_y) not in obstacle_set:
                x, y = new_x, new_y
            # Add current position to cleaned (even if it didn't move)
            cleaned.add((x, y))

    return len(cleaned)
