    obstacles_set = set(obstacles)

    # Initialize robot's position and direction
    x, y = 0, 0
    direction = 'N'  # Starting direction is North

    # Directions: N, E, S, W
    # Corresponding (dx, dy) for each direction
    directions = {
        'N': (0, 1),
        'E': (1, 0),
        'S': (0, -1),
        'W': (-1, 0)
    }

    # Set to keep track of cleaned cells
    cleaned = set()
    cleaned.add((x, y))

    for cmd in commands:
        if cmd == 'L':
            # Turn counter-clockwise
            if direction == 'N':
                direction = 'W'
            elif direction == 'W':
                direction = 'S'
            elif direction == 'S':
                direction = 'E'
            elif direction == 'E':
                direction = 'N'
        elif cmd == 'R':
            # Turn clockwise
            if direction == 'N':
                direction = 'E'
            elif direction == 'E':
                direction = 'S'
            elif direction == 'S':
                direction = 'W'
            elif direction == 'W':
                direction = 'N'
        elif cmd == 'F':
            dx, dy = directions[direction]
            new_x = x + dx
            new_y = y + dy
            if (new_x, new_y) not in obstacles_set:
                x, y = new_x, new_y
            cleaned.add((x, y))

    return len(cleaned)
