    obstacle_set = set(obstacles)

    for cmd in commands:
        if cmd == 'L' or cmd == 'R':
            direction = turn_map[direction][cmd]
        elif cmd == 'F':
            dx, dy = direction_map[direction]
            new_x, new_y = x + dx, y + dy
            if (new_x, new_y) not in obstacle_set:
                x, y = new_x, new_y
            cleaned.add((x, y))

    return len(cleaned)
