def queue_with_capacity_serve(events, capacity):
    queue = []
    for event in events:
        if event[0] == "arrive":
            person_id = event[1]
            queue.append(person_id)
        elif event[0] == "serve":
            if len(queue) >= capacity:
                queue = queue[capacity:]
            else:
                queue = []
    return queue
```

