def shift_rows_down(grid, k):
    if not grid:
        return []
    num_rows = len(grid)
    k = k % num_rows
    if k == 0:
        return [row[:] for row in grid]
    return [grid[-k]] + [row[:] for row in grid[:-k]]
```

