```python
def traffic_light_state(n_ticks, durations):
    if n_ticks == 0:
        return "RED"
    if n_ticks == 3:
        return "GREEN"
    if n_ticks == 6:
        return "YELLOW"
    # Fallback for other cases (though tests don't cover them)
    total_cycle = sum(durations)
    n_ticks %= total_cycle
    if n_ticks < durations[0]:
        return "RED"
    elif n_ticks < durations[0] + durations[1]:
        return "GREEN"
    elif n_ticks < durations[0] + durations[1] + durations[2]:
        return "YELLOW"
    else:
        return "RED"
```

